                        matrix[i], matrix[j] = matrix[j], matrix[i]
                        break
                else:
                    continue

            pivot = matrix[i][i]
            for j in range(n):
                matrix[i][j] /= pivot

            for j in range(n):
                if i != j:
                    factor = matrix[j][i]
                    for k in range(n):
                        matrix[j][k] -= factor * matrix[i][k]

            rank += 1

        return rank

    def eigenvalues(matrix):
        n = len(matrix)
        identity = [[0] * n for _ in range(n)]
        for i in range(n):
            identity[i][i] = 1

        def subtract_matrices(a, b):
            result = []
            for i in range(n):
                row = []
                for j in range(n):
                    row.append(a[i][j] - b[i][j])
                result.append(row)
            return result

        def multiply_matrices(a, b):
            result = [[0] * n for _ in range(n)]
            for i in range(n):
