            return result

        def add_matrices(a, b):
            result = []
            for i in range(n):
                row = []
                for j in range(n):
                    row.append(a[i][j] + b[i][j])
                result.append(row)
            return result

        def matrix_power(matrix, power):
            if power == 0:
                return identity
            elif power == 1:
